<template><div class="art-full-height page"><ArtSearchBar v-model="filters" :items="[{label:'手机号',key:'phone',type:'input',props:{placeholder:'请输入手机号'}},{label:'银行卡号',key:'card',type:'input',props:{placeholder:'请输入银行卡号'}},{label:'开户行',key:'bank',type:'input',props:{placeholder:'请输入开户行'}}]" :show-expand="false" @search="load" @reset="reset"/><ElCard class="art-table-card"><ArtTableHeader :loading="loading" @refresh="load"/><ElTable v-loading="loading" :data="rows"><ElTableColumn type="index" label="序号"/><ElTableColumn prop="phone" label="手机号"/><ElTableColumn prop="bank_card" label="银行卡号" min-width="180"/><ElTableColumn prop="name" label="持卡人姓名"/><ElTableColumn prop="id_card" label="身份证号" min-width="180"/><ElTableColumn prop="bank_name" label="开户行"/><ElTableColumn prop="bank_address" label="开户地址" min-width="180"/><ElTableColumn prop="updated_at" label="更新时间" min-width="170"/></ElTable></ElCard></div></template>
<script setup lang="ts">import{fetchCustomers,type Customer}from'@/api/system-manage';defineOptions({name:'UserBanks'});const loading=ref(false),rows=ref<Customer[]>([]),filters=reactive({phone:'',card:'',bank:''});const load=async()=>{loading.value=true;try{const data=await fetchCustomers({phone:filters.phone,page:1,pageSize:100});rows.value=data.records.filter(x=>(!filters.card||x.bank_card.includes(filters.card))&&(!filters.bank||x.bank_name.includes(filters.bank)))}finally{loading.value=false}};const reset=()=>{Object.assign(filters,{phone:'',card:'',bank:''});load()};onMounted(load)</script><style scoped>.page{display:flex;flex-direction:column;gap:12px}.art-table-card{flex:1}</style>